/** Resolve the configured card type for a card id via its prefix (e.g. `F-005` → `feature`). */
export function getCardType(cardTypes: CardTypeConfig[], id: string): string | undefined {
    const prefix = getCardIdPrefix(id)

    return cardTypes.find((cardType) => cardType.idPrefix === prefix)?.type
}

type MarkdownContextCard = Pick<Card, 'path'> & {
    header: Pick<CardHeader, 'id' | 'internalId' | 'status' | 'title' | 'worktreeError' | 'worktreeValue'>
}

function markdownContext(card: MarkdownContextCard, cardTypes: CardTypeConfig[], kind: ActionContextKind): ActionContext {
    const context: ActionContext = { file: card.path, kind, title: card.header.title }
    const type = getCardType(cardTypes, card.header.id)
    if (card.header.internalId) context.cardInternalId = card.header.internalId
    if (type) context.type = type
    if (card.header.status) context.state = card.header.status
    if (card.header.worktreeValue) context.worktree = card.header.worktreeValue
    if (card.header.worktreeError) context.worktreeError = card.header.worktreeError

    return context
}

/** Build the action context for a card shown in card view. */
export function cardContext(card: MarkdownContextCard, cardTypes: CardTypeConfig[]): ActionContext {
    if (!card.header.internalId) throw new Error(`Cannot build action context without an internal ID: ${card.path}`)

    return markdownContext(card, cardTypes, 'card')
}

/**
 * Build the action context for a markdown file in the tree/text view. Regular markdown files
 * are not cards and carry no internal ID, so the context stays without card identity.
 */
export function fileContext(card: Card, cardTypes: CardTypeConfig[]): ActionContext {
    return markdownContext(card, cardTypes, 'file')
}

/** Build the action context for a folder node in the tree. */
export function folderContext(folder: string, isSpecial = false): ActionContext {
    const context: ActionContext = { folder, kind: 'folder' }
    if (isSpecial) context.type = folder

    return context
}

/** Build context for actions that run against the opened project rather than a card or file. */
export function projectContext(): ActionContext {
    return { kind: 'project' }
}

/** Add or remove the session assignment used by project-wide popup actions. */
export function projectContextWithWorktree(context: ActionContext, worktree: number | null): ActionContext {
    if (context.kind !== 'project') return context
    if (worktree === null) {
        const unassignedContext = { ...context }
        delete unassignedContext.worktree

        return unassignedContext
    }

    return { ...context, worktree: String(worktree) }
}

/**
 * True when the action is allowed in the given context. An action with no
 * `appliesTo` (like the built-in custom prompt) matches every context; otherwise
 * every `appliesTo` key must equal the same field on the context.
 */
export function actionMatchesContext(action: ActionDefinition, context: ActionContext): boolean {
    if (!action.appliesTo) return true

    return ACTION_APPLIES_TO_FIELDS.every((key) => action.appliesTo?.[key] === undefined || context[key] === action.appliesTo[key])
}

/** All actions that should be shown for a context, preserving load order. */
export function actionsForContext(actions: ActionDefinition[], context: ActionContext): ActionDefinition[] {
    return actions.filter((action) => (!action.builtin || action.id === CUSTOM_PROMPT_ACTION_ID) && actionMatchesContext(action, context))
}

/** Context actions in selector order, with the built-in custom prompt last. */
export function displayActionsForContext(actions: ActionDefinition[], context: ActionContext): ActionDefinition[] {
    const contextActions = actionsForContext(actions, context)
    const customPrompt = contextActions.find(({ id }) => id === CUSTOM_PROMPT_ACTION_ID)
    const configuredActions = contextActions.filter(({ id }) => id !== CUSTOM_PROMPT_ACTION_ID)

    return customPrompt ? [...configuredActions, customPrompt] : configuredActions
}

import { useMediaQuery, useTheme } from '@mui/material'
import { useSyncExternalStore } from 'react'
import {
    cardPopupService,
    subscribeCardPopups,
} from '../../../../services/card_popup_service'
import { CardActionPopupHostEntry } from './card_action_popup_host_entry'
import { useWorkspaceView } from '../../../hooks/use_workspace_view'

/** Stable renderer for all service-owned card action popups. */
export function CardActionPopupHost() {
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const { viewMode } = useWorkspaceView()
    const entries = useSyncExternalStore(
        subscribeCardPopups,
        () => cardPopupService.getSnapshot(),
        () => cardPopupService.getSnapshot(),
    )
    const topEntryId = entries.at(-1)?.id

    return entries.map((entry, stackPosition) => entry.kind === 'action' ? (
        <CardActionPopupHostEntry
            entry={entry}
            key={entry.id}
            stackPosition={stackPosition}
            visible={viewMode !== 'stats' && (!isMobile || entry.id === topEntryId)}
        />
    ) : null)
}
import {
    cardPopupService,
    type CardActionPopupEntry,
} from '../../../../services/card_popup_service'
import { ActionPopup } from './action_popup'

interface CardActionPopupHostEntryProps {
    entry: CardActionPopupEntry
    stackPosition: number
    visible: boolean
}

/** Renders one service-owned card action popup with isolated local controller state. */
export function CardActionPopupHostEntry({ entry, stackPosition, visible }: CardActionPopupHostEntryProps) {
    const handleClose = () => {
        cardPopupService.close(entry.id)
    }

    const handleActivate = () => {
        cardPopupService.activate(entry.id)
    }

    const anchorElement = entry.anchorElement.isConnected ? entry.anchorElement : entry.fallbackAnchorElement

    return (
        <ActionPopup
            anchorElement={anchorElement}
            context={entry.context}
            draggable
            onActivate={handleActivate}
            onClose={handleClose}
            open={visible}
            popupEntryId={entry.id}
            stackPosition={stackPosition}
        />
    )
}

import { actionContextIdentity, type ActionContext } from '../data/action_context'
import type { CardCommit } from './actions/card_commit_history'
import {
    dataService,
    type DataService,
} from './data/data_service'
import { register } from './service_injector'

const CARD_POPUPS_CHANGED_EVENT = 'changed'

interface CardPopupEntryBase {
    anchorElement: HTMLElement
    fallbackAnchorElement: HTMLElement
    id: string
}

export interface CardActionPopupEntry extends CardPopupEntryBase {
    context: ActionContext
    kind: 'action'
}

export type CardDetailsDiffSelection =
    | { cardInternalId: string, commit: CardCommit, kind: 'commit' }
    | { kind: 'worktree' }

export interface CardDetailsPopupEntry extends CardPopupEntryBase {
    cardInternalId: string
    diffSelection: CardDetailsDiffSelection | null
    kind: 'card-details'
}

export type CardPopupEntry = CardActionPopupEntry | CardDetailsPopupEntry

function projectKey(service: DataService) {
    const project = service.getState().project

    return project ? `${project.id}:${project.branch}` : null
}

function createFallbackAnchor(anchorElement: HTMLElement) {
    const bounds = anchorElement.getBoundingClientRect()
    const fallbackAnchorElement = document.createElement('span')
    fallbackAnchorElement.setAttribute('aria-hidden', 'true')
    fallbackAnchorElement.dataset.cardPopupAnchor = 'true'
    Object.assign(fallbackAnchorElement.style, {
        height: `${bounds.height}px`,
        left: `${bounds.left}px`,
        pointerEvents: 'none',
        position: 'fixed',
        top: `${bounds.top}px`,
        visibility: 'hidden',
        width: `${bounds.width}px`,
    })
    document.body.append(fallbackAnchorElement)

    return fallbackAnchorElement
}

/** Owns ordered action and card-details popup entries across card component lifetimes. */
export class CardPopupService extends EventTarget {
    private readonly dataService: DataService
    private entries: CardPopupEntry[] = []
    private nextId = 1
    private currentProjectKey: string | null

    constructor(dataServiceInstance: DataService) {
        super()
        this.dataService = dataServiceInstance
        this.currentProjectKey = projectKey(this.dataService)
        this.dataService.addEventListener('changed', this.handleDataServiceChanged)
    }

    getSnapshot() {
        return this.entries
    }

    toggleAction(context: ActionContext, anchorElement: HTMLElement) {
        const contextIdentity = actionContextIdentity(context)
        const existing = this.entries.find((entry) => (
            entry.kind === 'action' && actionContextIdentity(entry.context) === contextIdentity
        ))
        if (existing) {
            this.close(existing.id)
            return
        }
        if (!context.cardInternalId) throw new Error('Cannot open a card action popup without a card internal ID')

        const entry: CardActionPopupEntry = {
            anchorElement,
            context: { ...context },
            fallbackAnchorElement: createFallbackAnchor(anchorElement),
            id: `card-action-popup-${this.nextId}`,
            kind: 'action',
        }
        this.nextId += 1
        this.setEntries([...this.entries, entry])
    }

    toggleCardDetails(cardInternalId: string, anchorElement: HTMLElement) {
        if (!cardInternalId) throw new Error('Cannot open card details without a card internal ID')

        const existing = this.findCardDetails(cardInternalId)
        if (existing) {
            this.close(existing.id)
            return
        }

        this.openCardDetails(cardInternalId, anchorElement, null)
    }

    openWorktreeDiff(cardInternalId: string, anchorElement: HTMLElement) {
        if (!cardInternalId) throw new Error('Cannot open worktree diff without a card internal ID')

        const existing = this.findCardDetails(cardInternalId)
        if (!existing) {
            this.openCardDetails(cardInternalId, anchorElement, { kind: 'worktree' })
            return
        }

        const updatedEntry = { ...existing, diffSelection: { kind: 'worktree' } as const }
        this.setEntries([
            ...this.entries.filter((entry) => entry.id !== existing.id),
            updatedEntry,
        ])
    }

    selectDiff(id: string, diffSelection: CardDetailsDiffSelection) {
        const entry = this.requireCardDetails(id)
        this.replaceEntry({ ...entry, diffSelection })
    }

    clearDiff(id: string) {
        const entry = this.requireCardDetails(id)
        if (!entry.diffSelection) return

        this.replaceEntry({ ...entry, diffSelection: null })
    }

    close(id: string) {
        const entry = this.entries.find((candidate) => candidate.id === id)
        if (!entry) return

        entry.fallbackAnchorElement.remove()
        this.setEntries(this.entries.filter((candidate) => candidate.id !== id))
    }

    closeCardDetailsByInternalId(cardInternalId: string) {
        this.removeEntries((entry) => entry.kind === 'card-details' && entry.cardInternalId === cardInternalId)
    }

    closeCardDetails() {
        this.removeEntries((entry) => entry.kind === 'card-details')
    }

    activate(id: string) {
        const entryIndex = this.entries.findIndex((entry) => entry.id === id)
        if (entryIndex < 0 || entryIndex === this.entries.length - 1) return

        const entry = this.entries[entryIndex]
        this.setEntries([...this.entries.filter((candidate) => candidate.id !== id), entry])
    }

    clear() {
        this.removeEntries(() => true)
    }

    private readonly handleDataServiceChanged = () => {
        const nextProjectKey = projectKey(this.dataService)
        if (nextProjectKey === this.currentProjectKey) return

        this.currentProjectKey = nextProjectKey
        this.clear()
    }

    private findCardDetails(cardInternalId: string) {
        return this.entries.find((entry): entry is CardDetailsPopupEntry => (
            entry.kind === 'card-details' && entry.cardInternalId === cardInternalId
        ))
    }

    private openCardDetails(
        cardInternalId: string,
        anchorElement: HTMLElement,
        diffSelection: CardDetailsDiffSelection | null,
    ) {
        const entry: CardDetailsPopupEntry = {
            anchorElement,
            cardInternalId,
            diffSelection,
            fallbackAnchorElement: createFallbackAnchor(anchorElement),
            id: `card-details-popup-${this.nextId}`,
            kind: 'card-details',
        }
        this.nextId += 1
        this.setEntries([...this.entries, entry])
    }

    private removeEntries(shouldRemove: (entry: CardPopupEntry) => boolean) {
        const removedEntries = this.entries.filter(shouldRemove)
        if (removedEntries.length === 0) return

        removedEntries.forEach(({ fallbackAnchorElement }) => fallbackAnchorElement.remove())
        this.setEntries(this.entries.filter((entry) => !shouldRemove(entry)))
    }

    private replaceEntry(replacement: CardPopupEntry) {
        this.setEntries(this.entries.map((entry) => entry.id === replacement.id ? replacement : entry))
    }

    private requireCardDetails(id: string) {
        const entry = this.entries.find((candidate): candidate is CardDetailsPopupEntry => (
            candidate.id === id && candidate.kind === 'card-details'
        ))
        if (!entry) throw new Error(`Card details popup does not exist: ${id}`)

        return entry
    }

    private setEntries(entries: CardPopupEntry[]) {
        this.entries = entries
        this.dispatchEvent(new Event(CARD_POPUPS_CHANGED_EVENT))
    }
}

export const cardPopupService = register('cardPopupService', new CardPopupService(dataService))

export function subscribeCardPopups(onStoreChange: () => void) {
    cardPopupService.addEventListener(CARD_POPUPS_CHANGED_EVENT, onStoreChange)

    return () => cardPopupService.removeEventListener(CARD_POPUPS_CHANGED_EVENT, onStoreChange)
}

import { Stack, Typography } from '@mui/material'
import type { ActionContext } from '../../../../data/action_context'
import type { ActionDefinition } from '../../../../data/action_types'
import { ActionConversationChatOwner } from '../../conversation/action_conversation_chat_owner'
import { ActionScheduleOwner } from '../schedule/action_schedule_owner'
import { ActionAgentInteraction } from './action_agent_interaction'
import { ActionRunDisabledMessage } from './action_run_disabled_message'
import type { ActionPopupRuntime } from './action_popup_types'

interface AgentActionProps {
    action: ActionDefinition
    assignmentContext: ActionContext
    baseContext: ActionContext
    popupEntryId?: string
    readOnlyMessage: string | null
    runtime: ActionPopupRuntime
}

/** Agent conversation, prompt, interaction, and scheduling content. */
export function AgentAction(props: AgentActionProps) {
    const { action, assignmentContext, baseContext, popupEntryId, readOnlyMessage, runtime } = props
    const { conversationStore, runValidationError, scheduleStore, settingsStore } = runtime

    if (readOnlyMessage) {
        return (
            <Stack data-testid="action-popup-scroll-body" spacing={2} sx={{ flex: 1, minHeight: 0, overflow: 'auto', px: 1.5, py: 1 }}>
                <ActionConversationChatOwner
                    actionId={action.id}
                    context={assignmentContext}
                    popupEntryId={popupEntryId}
                    store={conversationStore}
                />
                <Typography color="text.secondary" role="note" variant="caption">{readOnlyMessage}</Typography>
            </Stack>
        )
    }

    return (
        <Stack data-testid="action-popup-scroll-body" spacing={2} sx={{ flex: 1, minHeight: 0, overflow: 'auto', px: 1.5, py: 1 }}>
            <ActionAgentInteraction
                action={action}
                assignmentContext={assignmentContext}
                popupEntryId={popupEntryId}
                runtime={runtime}
            />
